#[cfg(test)]
mod tests {
    use super::add_dir_warning_message;
    use codex_protocol::models::ManagedFileSystemPermissions;
    use codex_protocol::models::PermissionProfile;
    use codex_protocol::permissions::FileSystemAccessMode;
    use codex_protocol::permissions::FileSystemPath;
    use codex_protocol::permissions::FileSystemSandboxEntry;
    use codex_protocol::permissions::FileSystemSpecialPath;
    use codex_protocol::permissions::NetworkSandboxPolicy;
    use pretty_assertions::assert_eq;
    use std::path::Path;
    use std::path::PathBuf;

    #[test]
    fn returns_none_for_workspace_write() {
        let profile = PermissionProfile::workspace_write();
        let dirs = vec![PathBuf::from("/tmp/example")];
        assert_eq!(
            add_dir_warning_message(&dirs, &profile, Path::new("/tmp/project")),
            None
        );
    }

    #[test]
    fn returns_none_for_danger_full_access() {
        let profile = PermissionProfile::Disabled;
        let dirs = vec![PathBuf::from("/tmp/example")];
        assert_eq!(
            add_dir_warning_message(&dirs, &profile, Path::new("/tmp/project")),
            None
        );
    }

    #[test]
    fn returns_none_for_external_sandbox() {
        let profile: PermissionProfile = PermissionProfile::External {
            network: NetworkSandboxPolicy::Enabled,
        };
        let dirs = vec![PathBuf::from("/tmp/example")];
        assert_eq!(
            add_dir_warning_message(&dirs, &profile, Path::new("/tmp/project")),
            None
        );
    }

    #[test]
    fn warns_for_read_only() {
        let profile = PermissionProfile::read_only();
        let dirs = vec![PathBuf::from("relative"), PathBuf::from("/abs")];
        let message = add_dir_warning_message(&dirs, &profile, Path::new("/tmp/project"))
            .expect("expected warning for read-only sandbox");
        assert_eq!(
            message,
            "Ignoring --add-dir (relative, /abs) because the effective permissions do not allow additional writable roots. Switch to workspace-write or danger-full-access to allow them."
        );
    }

    #[test]
    fn warns_when_profile_can_write_elsewhere_but_not_cwd() {
        let profile: PermissionProfile = PermissionProfile::Managed {
            network: NetworkSandboxPolicy::Restricted,
            file_system: ManagedFileSystemPermissions::Restricted {
                entries: vec![
                    FileSystemSandboxEntry {
                        path: FileSystemPath::Special {
                            value: FileSystemSpecialPath::Root,
                        },
                        access: FileSystemAccessMode::Read,
                        missing_path_behavior: None,
                    },
                    FileSystemSandboxEntry {
                        path: FileSystemPath::Path {
                            path: codex_utils_absolute_path::AbsolutePathBuf::try_from(
                                "/tmp/writable",
                            )
                            .expect("absolute path")
                            .into(),
                        },
                        access: FileSystemAccessMode::Write,
                        missing_path_behavior: None,
                    },
                ],
                glob_scan_max_depth: None,
            },
        };
        let dirs = vec![PathBuf::from("/tmp/extra")];

        assert_eq!(
            add_dir_warning_message(&dirs, &profile, Path::new("/tmp/project")),
            Some("Ignoring --add-dir (/tmp/extra) because the effective permissions do not allow additional writable roots. Switch to workspace-write or danger-full-access to allow them.".to_string())
        );
    }

    #[test]
    fn returns_none_when_no_additional_dirs() {
        let profile = PermissionProfile::read_only();
        let dirs: Vec<PathBuf> = Vec::new();
        assert_eq!(
            add_dir_warning_message(&dirs, &profile, Path::new("/tmp/project")),
            None
        );
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use pretty_assertions::assert_eq;

    fn populated_state() -> (AgentNavigationState, ThreadId, ThreadId, ThreadId) {
        let mut state = AgentNavigationState::default();
        let main_thread_id =
            ThreadId::from_string("00000000-0000-0000-0000-000000000101").expect("valid thread");
        let first_agent_id =
            ThreadId::from_string("00000000-0000-0000-0000-000000000102").expect("valid thread");
        let second_agent_id =
            ThreadId::from_string("00000000-0000-0000-0000-000000000103").expect("valid thread");

        state.upsert(
            main_thread_id,
            /*agent_nickname*/ None,
            /*agent_role*/ None,
            /*is_closed*/ false,
        );
        state.upsert(
            first_agent_id,
            Some("Robie".to_string()),
            Some("explorer".to_string()),
            /*is_closed*/ false,
        );
        state.upsert(
            second_agent_id,
            Some("Bob".to_string()),
            Some("worker".to_string()),
            /*is_closed*/ false,
        );

        (state, main_thread_id, first_agent_id, second_agent_id)
    }

    #[test]
    fn upsert_preserves_first_seen_order() {
        let (mut state, main_thread_id, first_agent_id, second_agent_id) = populated_state();

        state.upsert(
            first_agent_id,
            Some("Robie".to_string()),
            Some("worker".to_string()),
            /*is_closed*/ true,
        );

        assert_eq!(
            state.ordered_thread_ids(),
            vec![main_thread_id, first_agent_id, second_agent_id]
        );
    }

    #[test]
    fn parent_owned_state_is_removed_with_thread_metadata() {
        let (mut state, _main_thread_id, first_agent_id, second_agent_id) = populated_state();

        state.mark_parent_owned(first_agent_id);
        assert!(state.is_parent_owned(first_agent_id));
        state.remove(first_agent_id);
        assert!(!state.is_parent_owned(first_agent_id));

        state.mark_parent_owned(second_agent_id);
        state.clear();
        assert!(!state.is_parent_owned(second_agent_id));
    }

    #[test]
    fn picker_refresh_rejects_responses_from_before_clear() {
        let mut state = AgentNavigationState::default();
        let thread_id = ThreadId::new();
        let stale_request = state
            .begin_picker_refresh(thread_id)
            .expect("first picker refresh");

        assert_eq!(state.begin_picker_refresh(thread_id), None);
        state.clear();
        let current_request = state
            .begin_picker_refresh(thread_id)
            .expect("refresh after session reset");

        assert!(
            state
                .finish_picker_refresh(thread_id, stale_request)
                .is_none()
        );
        assert!(
            state
                .finish_picker_refresh(thread_id, current_request)
                .is_some()
        );
        state.set_picker_thread_visibility(ThreadId::new(), AgentPickerThreadVisibility::Hidden);
        assert!(state.picker_excluded_threads.is_empty());
    }

    #[test]
    fn adjacent_thread_id_wraps_in_spawn_order() {
        let (state, main_thread_id, first_agent_id, second_agent_id) = populated_state();

        assert_eq!(
            state.adjacent_thread_id(Some(second_agent_id), AgentNavigationDirection::Next),
            Some(main_thread_id)
        );
        assert_eq!(
            state.adjacent_thread_id(Some(second_agent_id), AgentNavigationDirection::Previous),
            Some(first_agent_id)
        );
        assert_eq!(
            state.adjacent_thread_id(Some(main_thread_id), AgentNavigationDirection::Previous),
            Some(second_agent_id)
        );

        let mut state = state;
        state.set_agent_path(first_agent_id, Some("/root/first".to_string()));
        state.set_picker_thread_visibility(first_agent_id, AgentPickerThreadVisibility::Hidden);
        assert!(
            state
                .ordered_path_backed_subagent_threads(Some(main_thread_id))
                .is_empty()
        );
    }

    #[test]
    fn picker_subtitle_mentions_shortcuts() {
        let previous: Span<'static> = previous_agent_shortcut().into();
        let next: Span<'static> = next_agent_shortcut().into();
        let subtitle = AgentNavigationState::picker_subtitle();

        assert!(subtitle.contains(previous.content.as_ref()));
        assert!(subtitle.contains(next.content.as_ref()));
    }

    #[test]
    fn active_agent_label_tracks_current_thread() {
        let (state, main_thread_id, first_agent_id, _) = populated_state();

        assert_eq!(
            state.active_agent_label(Some(first_agent_id), Some(main_thread_id)),
            Some("Robie [explorer]".to_string())
        );
        assert_eq!(
            state.active_agent_label(Some(main_thread_id), Some(main_thread_id)),
            Some("Main [default]".to_string())
        );
    }
}

#[cfg(test)]
mod tests {
    use super::ServerNotificationThreadTarget;
    use super::server_notification_thread_target;
    use crate::test_support::PathBufExt;
    use crate::test_support::test_path_buf;
    use codex_app_server_protocol::GuardianWarningNotification;
    use codex_app_server_protocol::McpServerStartupState;
    use codex_app_server_protocol::McpServerStatusUpdatedNotification;
    use codex_app_server_protocol::ServerNotification;
    use codex_app_server_protocol::ThreadAttachmentOperation;
    use codex_app_server_protocol::ThreadAttachmentUpdatedNotification;
    use codex_app_server_protocol::ThreadSettings;
    use codex_app_server_protocol::ThreadSettingsUpdatedNotification;
    use codex_app_server_protocol::WarningNotification;
    use codex_protocol::ThreadId;
    use codex_protocol::config_types::CollaborationMode;
    use codex_protocol::config_types::ModeKind;
    use codex_protocol::config_types::Settings;
    use codex_protocol::openai_models::ReasoningEffort;
    use pretty_assertions::assert_eq;

    fn test_thread_settings() -> ThreadSettings {
        ThreadSettings {
            disabled_plugin_ids: Vec::new(),
            cwd: test_path_buf("/tmp/thread-settings").abs(),
            approval_policy: codex_app_server_protocol::AskForApproval::Never,
            approvals_reviewer: codex_app_server_protocol::ApprovalsReviewer::User,
            sandbox_policy: codex_app_server_protocol::SandboxPolicy::ReadOnly {
                network_access: false,
            },
            active_permission_profile: None,
            model: "gpt-5.4".to_string(),
            model_provider: "openai".to_string(),
            service_tier: None,
            effort: Some(ReasoningEffort::High),
            summary: None,
            collaboration_mode: CollaborationMode {
                mode: ModeKind::Default,
                settings: Settings {
                    model: "gpt-5.4".to_string(),
                    reasoning_effort: Some(ReasoningEffort::High),
                    developer_instructions: None,
                },
            },
            multi_agent_mode: Default::default(),
            personality: None,
        }
    }

    #[test]
    fn warning_notifications_without_threads_are_global() {
        let notification = ServerNotification::Warning(WarningNotification {
            thread_id: None,
            message: "warning".to_string(),
        });

        let target = server_notification_thread_target(&notification);

        assert_eq!(target, ServerNotificationThreadTarget::Global);
    }

    #[test]
    fn warning_notifications_route_to_threads_when_thread_id_is_present() {
        let thread_id = ThreadId::new();
        let notification = ServerNotification::Warning(WarningNotification {
            thread_id: Some(thread_id.to_string()),
            message: "warning".to_string(),
        });

        let target = server_notification_thread_target(&notification);

        assert_eq!(target, ServerNotificationThreadTarget::Thread(thread_id));
    }

    #[test]
    fn guardian_warning_notifications_route_to_threads() {
        let thread_id = ThreadId::new();
        let notification = ServerNotification::GuardianWarning(GuardianWarningNotification {
            thread_id: thread_id.to_string(),
            message: "warning".to_string(),
        });

        let target = server_notification_thread_target(&notification);

        assert_eq!(target, ServerNotificationThreadTarget::Thread(thread_id));
    }

    #[test]
    fn mcp_startup_notifications_route_to_threads() {
        let thread_id = ThreadId::new();
        let notification =
            ServerNotification::McpServerStatusUpdated(McpServerStatusUpdatedNotification {
                thread_id: Some(thread_id.to_string()),
                name: "sentry".to_string(),
                status: McpServerStartupState::Failed,
                error: Some("sentry is not logged in".to_string()),
                failure_reason: None,
            });

        let target = server_notification_thread_target(&notification);

        assert_eq!(target, ServerNotificationThreadTarget::Thread(thread_id));
    }

    #[test]
    fn mcp_startup_notifications_without_threads_are_app_scoped() {
        let notification =
            ServerNotification::McpServerStatusUpdated(McpServerStatusUpdatedNotification {
                thread_id: None,
                name: "sentry".to_string(),
                status: McpServerStartupState::Failed,
                error: Some("sentry is not logged in".to_string()),
                failure_reason: None,
            });

        let target = server_notification_thread_target(&notification);

        assert_eq!(target, ServerNotificationThreadTarget::AppScoped);
    }

    #[test]
    fn thread_settings_updated_notifications_route_to_threads() {
        let thread_id = ThreadId::new();
        let notification =
            ServerNotification::ThreadSettingsUpdated(ThreadSettingsUpdatedNotification {
                thread_id: thread_id.to_string(),
                thread_settings: test_thread_settings(),
            });

        let target = server_notification_thread_target(&notification);

        assert_eq!(target, ServerNotificationThreadTarget::Thread(thread_id));
    }

    #[test]
    fn thread_attachment_updated_notifications_route_to_threads() {
        let thread_id = ThreadId::new();
        let notification =
            ServerNotification::ThreadAttachmentUpdated(ThreadAttachmentUpdatedNotification {
                thread_id: thread_id.to_string(),
                attachment_type: "pull_request".to_string(),
                identity_key: r#"["github.com","openai","codex",123]"#.to_string(),
                attachment_id: "attachment-1".to_string(),
                operation: ThreadAttachmentOperation::Deleted,
            });

        let target = server_notification_thread_target(&notification);

        assert_eq!(target, ServerNotificationThreadTarget::Thread(thread_id));
    }
}

#[cfg(test)]
mod tests {
    use super::PendingAppServerRequests;
    use super::ResolvedAppServerRequest;
    use super::ResolvedThreadAppServerRequest;
    use super::UnsupportedAppServerRequest;
    use crate::app_command::AppCommand as Op;
    use codex_app_server_protocol::AdditionalFileSystemPermissions;
    use codex_app_server_protocol::AdditionalNetworkPermissions;
    use codex_app_server_protocol::CommandExecutionApprovalDecision;
    use codex_app_server_protocol::CommandExecutionRequestApprovalParams;
    use codex_app_server_protocol::FileChangeApprovalDecision;
    use codex_app_server_protocol::FileChangeRequestApprovalParams;
    use codex_app_server_protocol::McpElicitationObjectType;
    use codex_app_server_protocol::McpElicitationSchema;
    use codex_app_server_protocol::McpServerElicitationAction;
    use codex_app_server_protocol::McpServerElicitationRequest;
    use codex_app_server_protocol::McpServerElicitationRequestParams;
    use codex_app_server_protocol::PermissionGrantScope;
    use codex_app_server_protocol::PermissionsRequestApprovalParams;
    use codex_app_server_protocol::PermissionsRequestApprovalResponse;
    use codex_app_server_protocol::RequestId as AppServerRequestId;
    use codex_app_server_protocol::ServerRequest;
    use codex_app_server_protocol::ToolRequestUserInputAnswer;
    use codex_app_server_protocol::ToolRequestUserInputParams;
    use codex_app_server_protocol::ToolRequestUserInputResponse;
    use codex_protocol::models::FileSystemPermissions;
    use codex_protocol::models::NetworkPermissions;
    use codex_protocol::request_permissions::RequestPermissionProfile;
    use codex_utils_absolute_path::AbsolutePathBuf;
    use pretty_assertions::assert_eq;
    use serde_json::json;
    use std::collections::BTreeMap;
    use std::collections::HashMap;
    use std::path::PathBuf;

    #[test]
    fn resolves_exec_approval_through_app_server_request_id() {
        let mut pending = PendingAppServerRequests::default();
        let request = ServerRequest::CommandExecutionRequestApproval {
            request_id: AppServerRequestId::Integer(41),
            params: CommandExecutionRequestApprovalParams {
                kind: Default::default(),
                thread_id: "thread-1".to_string(),
                turn_id: "turn-1".to_string(),
                item_id: "call-1".to_string(),
                started_at_ms: 0,
                approval_id: Some("approval-1".to_string()),
                environment_id: None,
                reason: None,
                network_approval_context: None,
                command: Some("ls".to_string()),
                cwd: None,
                command_actions: None,
                additional_permissions: None,
                proposed_execpolicy_amendment: None,
                proposed_network_policy_amendments: None,
                available_decisions: None,
            },
        };

        assert_eq!(pending.note_server_request(&request), None);

        let resolution = pending
            .take_resolution(
                "thread-1",
                &Op::ExecApproval {
                    id: "approval-1".to_string(),
                    turn_id: None,
                    decision: CommandExecutionApprovalDecision::Accept,
                },
            )
            .expect("resolution should serialize")
            .expect("request should be pending");

        assert_eq!(resolution.request_id, AppServerRequestId::Integer(41));
        assert_eq!(resolution.result, json!({ "decision": "accept" }));
    }

    #[test]
    fn colliding_approvals_resolve_only_on_their_own_thread() {
        let approvals = [
            (
                "item/commandExecution/requestApproval",
                Op::ExecApproval {
                    id: "shared-id".to_string(),
                    turn_id: None,
                    decision: CommandExecutionApprovalDecision::Accept,
                },
            ),
            (
                "item/fileChange/requestApproval",
                Op::PatchApproval {
                    id: "shared-id".to_string(),
                    decision: FileChangeApprovalDecision::Accept,
                },
            ),
            (
                "item/permissions/requestApproval",
                Op::RequestPermissionsResponse {
                    id: "shared-id".to_string(),
                    response: codex_protocol::request_permissions::RequestPermissionsResponse {
                        permissions: RequestPermissionProfile::default(),
                        scope: codex_protocol::request_permissions::PermissionGrantScope::Turn,
                        strict_auto_review: false,
                    },
                },
            ),
        ];

        for (method, op) in approvals {
            let mut pending = PendingAppServerRequests::default();
            let thread_ids = [
                codex_protocol::ThreadId::new().to_string(),
                codex_protocol::ThreadId::new().to_string(),
            ];
            for (index, thread_id) in thread_ids.iter().enumerate() {
                let wire_thread_id = if index == 0 {
                    thread_id.to_ascii_uppercase()
                } else {
                    thread_id.replace('-', "")
                };
                let request: ServerRequest = serde_json::from_value(json!({
                    "method": method,
                    "id": index + 1,
                    "params": {
                        "threadId": wire_thread_id,
                        "turnId": "turn-1",
                        "itemId": "shared-id",
                        "startedAtMs": 0,
                        "cwd": if cfg!(windows) { r"C:\tmp" } else { "/tmp" },
                        "permissions": {},
                    },
                }))
                .expect("approval request should deserialize");
                assert_eq!(pending.note_server_request(&request), None);
                assert!(pending.contains_server_request(&request));
            }
            assert_eq!(
                pending.resolve_notification(&thread_ids[1], &AppServerRequestId::Integer(1)),
                None
            );

            for (thread_id, request_id) in thread_ids.iter().zip(1..=2) {
                let resolution = pending
                    .take_resolution(thread_id, &op)
                    .expect("approval resolution should serialize")
                    .expect("approval should remain pending on its own thread");
                assert_eq!(
                    resolution.request_id,
                    AppServerRequestId::Integer(request_id)
                );
            }
        }
    }

    #[test]
    fn rejects_permissions_with_paths_that_cannot_be_localized() {
        let mut pending = PendingAppServerRequests::default();
        let request_id = AppServerRequestId::Integer(7);
        let permissions = codex_app_server_protocol::RequestPermissionProfile {
            network: None,
            file_system: Some(AdditionalFileSystemPermissions {
                read: Some(vec![
                    serde_json::from_value(json!("relative/path"))
                        .expect("relative API path should deserialize"),
                ]),
                write: None,
                glob_scan_max_depth: None,
                entries: None,
            }),
        };
        let localization_error =
            RequestPermissionProfile::try_from(permissions.clone()).expect_err("relative path");
        let cwd = AbsolutePathBuf::try_from(PathBuf::from(if cfg!(windows) {
            r"C:\tmp"
        } else {
            "/tmp"
        }))
        .expect("path must be absolute");

        assert_eq!(
            pending.note_server_request(&ServerRequest::PermissionsRequestApproval {
                request_id: request_id.clone(),
                params: PermissionsRequestApprovalParams {
                    thread_id: "thread-1".to_string(),
                    turn_id: "turn-1".to_string(),
                    item_id: "perm-1".to_string(),
                    environment_id: None,
                    started_at_ms: 0,
                    cwd: cwd.into(),
                    reason: None,
                    permissions,
                },
            }),
            Some(UnsupportedAppServerRequest {
                request_id,
                message: format!(
                    "failed to localize requested filesystem paths: {localization_error}"
                ),
            })
        );
    }

    #[test]
    fn resolves_permissions_and_user_input_through_app_server_request_id() {
        let mut pending = PendingAppServerRequests::default();
        let read_path = if cfg!(windows) {
            r"C:\tmp\read-only"
        } else {
            "/tmp/read-only"
        };
        let write_path = if cfg!(windows) {
            r"C:\tmp\write"
        } else {
            "/tmp/write"
        };
        let absolute_path = |path: &str| {
            AbsolutePathBuf::try_from(PathBuf::from(path)).expect("path must be absolute")
        };

        assert_eq!(
            pending.note_server_request(&ServerRequest::PermissionsRequestApproval {
                request_id: AppServerRequestId::Integer(7),
                params: PermissionsRequestApprovalParams {
                    thread_id: "thread-1".to_string(),
                    turn_id: "turn-1".to_string(),
                    item_id: "perm-1".to_string(),
                    environment_id: None,
                    started_at_ms: 0,
                    cwd: absolute_path(if cfg!(windows) { r"C:\tmp" } else { "/tmp" }).into(),
                    reason: None,
                    permissions: serde_json::from_value(json!({
                        "network": { "enabled": null }
                    }))
                    .expect("valid permissions"),
                },
            }),
            None
        );
        assert_eq!(
            pending.note_server_request(&ServerRequest::ToolRequestUserInput {
                request_id: AppServerRequestId::Integer(8),
                params: ToolRequestUserInputParams {
                    thread_id: "thread-1".to_string(),
                    turn_id: "turn-2".to_string(),
                    item_id: "tool-1".to_string(),
                    questions: Vec::new(),
                    is_blocking: true,
                    auto_resolution_ms: None,
                },
            }),
            None
        );

        let permissions = pending
            .take_resolution(
                "thread-1",
                &Op::RequestPermissionsResponse {
                    id: "perm-1".to_string(),
                    response: codex_protocol::request_permissions::RequestPermissionsResponse {
                        permissions: RequestPermissionProfile {
                            network: Some(NetworkPermissions {
                                enabled: Some(true),
                            }),
                            file_system: Some(FileSystemPermissions::from_read_write_roots(
                                Some(vec![absolute_path(read_path)]),
                                Some(vec![absolute_path(write_path)]),
                            )),
                        },
                        scope: codex_protocol::request_permissions::PermissionGrantScope::Session,
                        strict_auto_review: false,
                    },
                },
            )
            .expect("permissions response should serialize")
            .expect("permissions request should be pending");
        assert_eq!(permissions.request_id, AppServerRequestId::Integer(7));
        assert_eq!(
            serde_json::from_value::<PermissionsRequestApprovalResponse>(permissions.result)
                .expect("permissions response should decode"),
            PermissionsRequestApprovalResponse {
                permissions: codex_app_server_protocol::GrantedPermissionProfile {
                    network: Some(AdditionalNetworkPermissions {
                        enabled: Some(true),
                    }),
                    file_system: Some(AdditionalFileSystemPermissions {
                        read: Some(vec![absolute_path(read_path).into()]),
                        write: Some(vec![absolute_path(write_path).into()]),
                        glob_scan_max_depth: None,
                        entries: Some(vec![
                            codex_app_server_protocol::FileSystemSandboxEntry {
                                path: codex_app_server_protocol::FileSystemPath::Path {
                                    path: absolute_path(read_path).into(),
                                },
                                access: codex_app_server_protocol::FileSystemAccessMode::Read,
                            },
                            codex_app_server_protocol::FileSystemSandboxEntry {
                                path: codex_app_server_protocol::FileSystemPath::Path {
                                    path: absolute_path(write_path).into(),
                                },
                                access: codex_app_server_protocol::FileSystemAccessMode::Write,
                            },
                        ]),
                    }),
                },
                scope: PermissionGrantScope::Session,
                strict_auto_review: None,
            }
        );

        let user_input = pending
            .take_resolution(
                "thread-1",
                &Op::UserInputAnswer {
                    id: "turn-2".to_string(),
                    response: ToolRequestUserInputResponse {
                        answers: std::iter::once((
                            "question".to_string(),
                            ToolRequestUserInputAnswer {
                                answers: vec!["yes".to_string()],
                            },
                        ))
                        .collect(),
                    },
                },
            )
            .expect("user input response should serialize")
            .expect("user input request should be pending");
        assert_eq!(user_input.request_id, AppServerRequestId::Integer(8));
        assert_eq!(
            serde_json::from_value::<ToolRequestUserInputResponse>(user_input.result)
                .expect("user input response should decode"),
            ToolRequestUserInputResponse {
