                    ])
                    .render(frame.area(), frame.buffer_mut());
                })
                .expect("restore composer");
        }

        let visible = terminal
            .backend()
            .vt100()
            .screen()
            .contents()
            .lines()
            .map(str::trim_end)
            .collect::<Vec<_>>()
            .join("\n");
        assert_snapshot!(visible.trim_end(), @r"
        Previous conversation




        › Ask Codex to do anything
        ");
    }

