        stack: &ConfigLayerStack,
        sandbox_mode_is_effectively_allowed: impl Fn(SandboxModeRequirement) -> bool,
    ) -> String {
        render_to_text(&render_debug_config_lines(
            stack,
            sandbox_mode_is_effectively_allowed,
        ))
    }

